27	const MAIN_TREE_POS = {"trees-shade-trunk":{"count":890,"sum":-3857311.434},"trees-shade-crown":{"count":890,"sum":-3857311.434},"trees-palm-trunk":{"count":246,"sum":1318102.245},"tp-trees-trunk":{"count":128,"sum":420346.507},"tp-trees-crown":{"count":128,"sum":420346.507}};
