35	const CAP = { 'trees-shade-trunk': 'shadeTrunk', 'trees-shade-crown': 'shadeCrown', 'trees-palm-trunk': 'palmTrunk', 'trees-palm-crown': 'palmCrown', 'tp-trees-trunk': 'shadeTrunk', 'tp-trees-crown': 'shadeCrown' };
