67	  const pos = {};
68	  for (const n of NAMES) {
69	    const p = await page.evaluate((n) => window.__app.trees.positions(n), n);
70	    let sum = 0; for (let i = 0; i < p.length; i += 2) sum += p[i] * 31 + p[i + 1];
71	    pos[n] = { count: p.length / 2, sum: Math.round(sum * 1000) / 1000, p };
72	  }
73	  const got = Object.fromEntries(POS_NAMES.map((n) => [n, { count: pos[n].count, sum: pos[n].sum }]));
74	  if (!MAIN_TREE_POS) console.log('MỐC MAIN_TREE_POS =', JSON.stringify(got));
75	  else for (const n of POS_NAMES) check(got[n].count === MAIN_TREE_POS[n].count && Math.abs(got[n].sum - MAIN_TREE_POS[n].sum) < 0.01, `posKept: ${n} ${got[n].count} instance, tổng kiểm ${got[n].sum} (mốc ${MAIN_TREE_POS[n].count}, ${MAIN_TREE_POS[n].sum})`);
76	  const t = pos['trees-palm-trunk'].p, c = pos['trees-palm-crown'].p; let far = 0;
