82	  check(rk.length === 7 && rk.every((s, i) => Math.abs(s - MAIN_BOAT_SPEEDS[i]) < 1e-12), `randKept: speed 7 tàu trùng main (${rk.map((s) => s.toFixed(3)).join(', ')})`);
83	
