86	  if (!tb.cap) check(false, 'trisBudget: __app.trees.maxTris chưa có');
87	  else for (const m of tb.list) check(m.tris <= tb.cap[CAP[m.name]], `trisBudget: ${m.name} ${m.tris} tam giác ≤ ${tb.cap[CAP[m.name]]}`);
88	
89	  /* ---------- 5. pairs ---------- */
90	  const pr = await page.evaluate(() => window.__app.weather.fallen.state().pairs);
91	  if (MAIN_PAIRS === null) console.log('MỐC MAIN_PAIRS =', pr);
92	  else check(pr === MAIN_PAIRS, `pairs: ${pr} cặp thân–tán (mốc ${MAIN_PAIRS})`);
93	
94	  /* ---------- 7. clearedStayZero (trước khi đổ cây) ---------- */
95	  const cleared = {};
96	  for (const [tn, cn] of PAIRS) {
