102	  else for (const [, cn] of PAIRS) check(cleared[cn] === MAIN_CLEARED[cn], `clearedStayZero: ${cn} số tán dọn ${cleared[cn]} (mốc ${MAIN_CLEARED[cn]})`);
103	
104	  /* ---------- 6. fallenRestore ---------- */
105	  await page.evaluate(() => { const { camera, controls } = window.__app; camera.position.set(-240, 30, 260); controls.target.set(-275, 3, 200); controls.update(); });
106	  await frames(page, 2);
107	  const before = await page.evaluate(() => window.__app.weather.fallen.snapshot());
108	  await page.evaluate(() => { const w = window.__app.weather; w.fallen.fell(); w.setParams({ wind: 3 }, true); });
