114	  check(fs.down > 0 && same, `fallenRestore: ${fs.down} cây đổ tới ${fs.angle.toFixed(3)} rad, dựng lại trùng ma trận gốc (${same})`);
115	  await page.evaluate(() => window.__app.weather.setParams({ wind: 0 }, true));
116	  await setWx(page, 'now');
117	
118	  /* ---------- 8. windAttached ---------- */
119	  await setWx(page, 'storm'); await frames(page, 30);
120	  const sw = await page.evaluate(() => window.__app.weather.sway());
121	  check(sw.treeLean > 0, `windAttached: bão ⇒ treeLean ${sw.treeLean.toFixed(4)} m/m, treeSway ${sw.treeSway.toFixed(4)} m/m`);
122	  check(!errors.some((e) => /shader|program/i.test(e)), 'windAttached: không lỗi biên dịch shader');
123	  await setWx(page, 'now'); await frames(page, 3);
124	
125	  /* ---------- 10. ảnh ---------- */
126	  if (!NO_SHOTS) {
127	    const shot = async (name) => { await frames(page, 4); await page.screenshot({ path: `${SCREENS}trees-${name}.png` }); };
128	    /* Đặt camera theo instance i của lưới (tọa độ thế giới): off = lệch camera (m), lookY = nhìn cao hơn gốc cây */
129	    const aim = (name, i, off, lookY) => page.evaluate(([name, i, off, lookY]) => {
130	      const a = window.__app, T = a.THREE, o = a.scene.getObjectByName(name), M = new T.Matrix4(), P = new T.Vector3();
131	      o.updateWorldMatrix(true, false); o.getMatrixAt(i, M); M.premultiply(o.matrixWorld); P.setFromMatrixPosition(M);
132	      a.camera.position.set(P.x + off[0], P.y + off[1], P.z + off[2]); a.controls.target.set(P.x, P.y + lookY, P.z); a.controls.update();
133	    }, [name, i, off, lookY]);
134	    /* Dừa bờ Tây gần z0 (chưa dọn) có cây bóng mát cạnh bên */
135	    const palmNear = (z0) => page.evaluate((z0) => { const p = window.__app.trees.positions('trees-palm-trunk'); let b = -1, d = 1e9; for (let i = 0; i < p.length; i += 2) if (p[i] < -262 && p[i] > -300 && Math.abs(p[i + 1] - z0) < d) { d = Math.abs(p[i + 1] - z0); b = i / 2; } return b; }, z0);
136	    const pi = await palmNear(230);
137	    await page.evaluate(() => window.__app.weather.fallen.stand());   // bão ở mục 8 rồi về 'now' ⇒ aftermath đã đổ cây quanh điểm nhìn; dựng lại cho ảnh gọn
138	    await pickView(page, 'dragon', 'overview'); await hideUi(true);
139	    await shot('toan-canh-ngay');
140	    await aim('trees-palm-trunk', pi, [17, 3, 10], 6); await shot('gan-bach-dang-ngay');
141	    await aim('trees-palm-trunk', pi, [22, 9, -14], 4); await shot('gan-bach-dang-ngay-2');
142	    const tpi = await page.evaluate(() => { const p = window.__app.trees.positions('tp-trees-trunk'); const n = p.length / 2; for (let k = 0; k < n; k++) { const i = (Math.floor(n / 3) + k) % n; if (p[i * 2] !== 0 || p[i * 2 + 1] !== 0) return i; } return 0; });
143	    await aim('tp-trees-trunk', tpi, [-25, 14, 30], 3); await shot('ke-thuan-phuoc');
144	    await setNight(1);
145	    const pn = await palmNear(-430);
146	    await aim('trees-palm-trunk', pn, [26, 8, 30], 4); await shot('di-bo-dem');
147	    await setNight(0);
148	    await setWx(page, 'storm'); await frames(page, 30);
149	    await aim('trees-palm-trunk', pi, [30, 6, 18], 6); await shot('bo-song-bao');
150	    await setWx(page, 'now');
151	    await hideUi(false);
152	  }
153	
154	  check(errors.length === 0, `không lỗi console (${errors.join(' | ')})`);
155	} finally {
156	  await browser.close(); srv.close();
157	}
158	console.log(problems.length ? `\n${problems.length} mục LỖI` : '\nTất cả ĐẠT');
159	process.exit(problems.length ? 1 : 0);
