  const cp = bridge.concreteParts, tg = new THREE.CylinderGeometry(0.22, 0.35, 1, 6).translate(0, 0.5, 0), cg = new THREE.ConeGeometry(1, 1, 9, 1, true);
  palms.forEach(([x, z]) => {
